# ------------------------------------------------------------------ the annotated process map (overview)
# Draft 3: the overview is a plain-language process map (not BPMN). Each stage shows its number, title, who acts with what
# authority ("who"), one or two callouts ("pointers"), at most one "runs" line (repeats, waits or work side by side) and its
# decisions ("gates": question and labelled outcomes). The full receives / does / hands over contract, rules, exceptions,
# examples and links to the activity cards sit in the stage's panel. One source for the map, the panels and the checks.
# Stage keys: n, title, actors, who, receives, does, produces, to, pointers, runs, gates, handoff (label on the arrow to the
# next stage), and the panel: before, rules, exceptions, example (blocks as for activities), acts.
def ST(**k):
    for f in ("before", "rules", "exceptions", "example", "pointers", "gates"): k.setdefault(f, [])
    k.setdefault("handoff", ""); k.setdefault("runs", None)
    k.setdefault("who", [(a, "") for a in k.get("actors", [])])
    return k

